effect.shader:
void main(){
vec2 uv = acScreenNorm;
float t = acTime * wobbleSpeed + wobblePhase;
vec2 anchor = vec2(anchorX * 0.01, anchorY * 0.01);
vec2 p = uv - anchor;
float pulse = 1.0 - jellyPulse * 0.03 * sin(t * 2.0);
p *= pulse;
float wx = sin(p.y * wobbleFreq * 6.2831 + t * 1.7) * 0.012 * wobbleX;
float wy = sin(p.x * wobbleFreq * 5.3 + t * 1.3) * 0.012 * wobbleY;
vec2 suv = anchor + p + vec2(wx, wy);
vec4 col = texture2DCv(inputImg.texture, clamp(suv, 0.0, 1.0));
gl_FragColor = vec4(col.rgb, col.a);
}
